std::atomic<unsigned long long> g_calls[kFnCount], g_mismatches[kFnCount];
HANDLE g_log = INVALID_HANDLE_VALUE;

void AppendLog(const std::string& text)
{
    if (g_log == INVALID_HANDLE_VALUE) return;
    DWORD written = 0;
    // FILE_APPEND_DATA without FILE_WRITE_DATA: each complete message/block appends
    // atomically. No CRT or user mutex can be stranded by thread teardown at exit.
    WriteFile(g_log, text.data(), static_cast<DWORD>(text.size()), &written, nullptr);
}
HANDLE g_stopEvent = nullptr;
HANDLE g_reportThread = nullptr;

void Log(const char* fmt, ...)
{
    char buffer[8192];
    va_list ap;
    va_start(ap, fmt);
    std::vsnprintf(buffer, sizeof buffer, fmt, ap);
    va_end(ap);
    AppendLog(std::string(buffer) + "\r\n");
}
std::atomic<unsigned> g_details[kFnCount];
void Mismatch(Fn fn, const char* fmt, ...)
{
    ++g_mismatches[fn];
    if (g_details[fn].fetch_add(1) >= 5) return;
    char message[1024];
    va_list ap;
    va_start(ap, fmt);
    std::vsnprintf(message, sizeof message, fmt, ap);
    va_end(ap);
    Log("MISMATCH %s: %s", kFnNames[fn], message);
}
using PatchFn = void(__cdecl*)();
#define Slot(fn) reinterpret_cast<void**>(&(fn))
std::string Hex(const void* p, size_t n, size_t max = 48)
{
    std::string s;
    char b[4];
    const auto* u = static_cast<const uint8_t*>(p);
    for (size_t i = 0; i < n && i < max; ++i) {
        std::snprintf(b, sizeof b, "%02x", u[i]);
        s += b;
    }
    if (n > max)
        s += "...";
    return s;
}

std::string Printable(const char* s, uint32_t len)
{
    std::string out;
    for (uint32_t i = 0; i < len && i < 160; ++i) {
        const auto c = static_cast<uint8_t>(s[i]);
        if (c >= 0x20 && c < 0x7F) {
            out += static_cast<char>(c);
        } else {
            char b[8];
            std::snprintf(b, sizeof b, "\\x%02x", c);
            out += b;
        }
    }
    return out;
}

std::string PrintableW(const wchar_t* s, uint32_t len)
{
    std::string out;
    for (uint32_t i = 0; i < len && i < 160; ++i) {
        const auto c = static_cast<uint16_t>(s[i]);
        if (c >= 0x20 && c < 0x7F) {
            out += static_cast<char>(c);
        } else {
            char b[10];
            std::snprintf(b, sizeof b, "\\u%04x", c);
            out += b;
        }
    }
    return out;
}

