int __stdcall CmpIsRefPack(const void* src, uint32_t len)
{
    ++g_calls[kIsRefPack];
    const int o = g_orig.isRefPack(src, len);
    const bool r = ts3::refpack::IsCompressed(src);
    if ((o != 0) != r)
        Mismatch(kIsRefPack, "header %s: original %d, rewrite %d", Hex(src, 2).c_str(), o, r);
    return o;
}

uint32_t __stdcall CmpDecompress(const void* src, uint32_t len, void* dst, uint32_t cap, uint32_t x)
{
    ++g_calls[kDecompress];

    thread_local std::vector<uint8_t> scratch;
    std::vector<uint8_t> before;
    const uint32_t o = g_orig.decompress(src, len, dst, cap, x);
    uint32_t r;
    if (dst == nullptr) {
        r = ts3::refpack::Decompress(src, len, nullptr, 0);
    } else {
        scratch.assign(cap, 0);
        r = ts3::refpack::Decompress(src, len, scratch.data(), cap);
    }
    if (r != o) {
        Mismatch(kDecompress, "len %u dst %p cap %u: original %u, rewrite %u; src %s", len, dst, cap, o, r,
                 Hex(src, std::min<uint32_t>(len, 16)).c_str());
    } else if (dst && o != 0 && o != ts3::refpack::kError) {
        const uint32_t n = std::min(o, cap);
        if (std::memcmp(dst, scratch.data(), n) != 0) {
            uint32_t at = 0;
            while (at < n && static_cast<const uint8_t*>(dst)[at] == scratch[at])
                ++at;
            Mismatch(kDecompress, "len %u cap %u size %u: output differs at %u; src %s", len, cap, o, at,
                     Hex(src, std::min<uint32_t>(len, 16)).c_str());
        }
    }
    return o;
}

uint32_t __cdecl CmpDecode(uint8_t* dst, uint32_t cap, const uint8_t* src, uint32_t len)
{
    ++g_calls[kDecode];
    thread_local std::vector<uint8_t> scratch;
    const uint32_t o = g_orig.decode(dst, cap, src, len);
    scratch.assign(cap, 0);
    const uint32_t r = ts3::refpack::Decode(scratch.data(), cap, src, len);
    if (r != o)
        Mismatch(kDecode, "len %u cap %u: original %u, rewrite %u; src %s", len, cap, o, r,
                 Hex(src, std::min<uint32_t>(len, 16)).c_str());
    else if (o && std::memcmp(dst, scratch.data(), std::min(o, cap)) != 0)
        Mismatch(kDecode, "len %u cap %u size %u: output differs", len, cap, o);
    return o;
}

uint32_t __cdecl CmpReadBE(const uint8_t* p, int bytes)
{
    ++g_calls[kReadBE];
    const uint32_t o = g_orig.readBE(p, bytes);
    const uint32_t r = ts3::refpack::ReadBigEndian(p, bytes);
    if (o != r)
        Mismatch(kReadBE, "bytes %d data %s: original %08x, rewrite %08x", bytes, Hex(p, 4).c_str(), o, r);
    return o;
}

uint32_t __cdecl CmpFnv32(const char* s, uint32_t len)
{
    ++g_calls[kFnv32];
    const uint32_t o = g_orig.fnv32(s, len);
    const uint32_t r = ts3::hash::Fnv32Lower(s, len);
    if (o != r)
        Mismatch(kFnv32, "len %u \"%s\": original %08x, rewrite %08x", len, Printable(s, len).c_str(), o, r);
    return o;
}

uint64_t __cdecl CmpFnv64W(const wchar_t* s, uint32_t len)
{
    ++g_calls[kFnv64];
    const uint64_t o = g_orig.fnv64w(s, len);
    const uint64_t r = ts3::hash::Fnv64LowerW(reinterpret_cast<const char16_t*>(s), len);
    if (o != r)
        Mismatch(kFnv64, "len %u \"%s\": original %016llx, rewrite %016llx", len, PrintableW(s, len).c_str(), o, r);
    return o;
}

