std::vector<uint8_t>& Scratch(const void* snapshotOf, size_t size)
{
    thread_local std::vector<uint8_t> scratch;
    if (scratch.size() < size)
        scratch.resize(size);
    if (size)
        std::memcpy(scratch.data(), snapshotOf, size);
    return scratch;
}

