static constexpr int ModRmLen(const uint8_t* p, int avail, int* pi)
{
    int i = *pi;
    if (i >= avail)
        return -1;
    const uint8_t m = p[i++];
    const int mod = m >> 6, rm = m & 7;
    if (mod != 3) {
        if (rm == 4) {  
            if (i >= avail)
                return -1;
            const uint8_t sib = p[i++];
            if (mod == 0 && (sib & 7) == 5)
                i += 4;  
        } else if (mod == 0 && rm == 5) {
            i += 4;  
        }
        if (mod == 1)
            i += 1;
        else if (mod == 2)
            i += 4;
        if (i > avail)
            return -1;
    }
    *pi = i;
    return m;
}

static constexpr int InsnLen(const uint8_t* p, int avail)
{
    int i = 0;
    bool op16 = false;
    while (i < avail) {
        const uint8_t b = p[i];
        if (b == 0x66)
            op16 = true;
        else if (b != 0xF0 && b != 0xF2 && b != 0xF3 && b != 0x26 && b != 0x2E && b != 0x36 &&
                 b != 0x3E && b != 0x64 && b != 0x65)
            break;
        ++i;
    }
    if (i >= avail)
        return 0;
    const uint8_t op = p[i++];
    const int immsz = op16 ? 2 : 4;
    auto need = [&](int n) {
        if (i + n > avail)
            return false;
        i += n;
        return true;
    };
    auto modrm = [&]() { return ModRmLen(p, avail, &i) < 0 ? 0 : i; };

    const bool branch = (op >= 0x70 && op <= 0x7F) || op == 0xEB || op == 0xE8 || op == 0xE9 ||
                        (op == 0x0F && i < avail && p[i] >= 0x80 && p[i] <= 0x8F);
    if (branch && i > 1)
        return 0;
    if (op >= 0x70 && op <= 0x7F)
        return need(1) ? i : 0;  
    if (op == 0xEB)
        return need(1) ? i : 0;  
    if (op == 0xE8 || op == 0xE9)
        return need(4) ? i : 0;  

    if (op == 0x0F) {  
        if (i >= avail)
            return 0;
        const uint8_t op2 = p[i++];
        if (op2 >= 0x80 && op2 <= 0x8F)
            return need(4) ? i : 0;  

        if ((op2 >= 0x40 && op2 <= 0x4F) || (op2 >= 0x50 && op2 <= 0x5F) ||
            (op2 >= 0x90 && op2 <= 0x9F) || (op2 >= 0x10 && op2 <= 0x17) || op2 == 0x28 ||
            op2 == 0x29 || op2 == 0x2E || op2 == 0x2F || op2 == 0x6E || op2 == 0x6F ||
            op2 == 0x7E || op2 == 0x7F || op2 == 0xAF || op2 == 0xB6 || op2 == 0xB7 ||
            op2 == 0xBC || op2 == 0xBD || op2 == 0xBE || op2 == 0xBF)
            return modrm();
        return 0;
    }
    if (op < 0x40) {  
        const int lo = op & 7;
        if (lo <= 3)
            return modrm();
        if (lo == 4)
            return need(1) ? i : 0;
        if (lo == 5)
            return need(immsz) ? i : 0;
        return 0;
    }
    if (op <= 0x67) {  
        if (op <= 0x61)
            return i;
        if (op == 0x62 || op == 0x63)
            return modrm();
        return 0;  
    }
    if (op == 0x68)
        return need(immsz) ? i : 0;  
    if (op == 0x6A)
        return need(1) ? i : 0;
    if (op == 0x69 || op == 0x6B) {  
        if (modrm() == 0)
            return 0;
        return need(op == 0x69 ? immsz : 1) ? i : 0;
    }
    if (op >= 0x6C && op <= 0x6F)
        return i;  
    if (op == 0x80 || op == 0x81 || op == 0x83) {  
        if (modrm() == 0)
            return 0;
        return need(op == 0x81 ? immsz : 1) ? i : 0;
    }
    if (op >= 0x84 && op <= 0x8F)  
        return modrm();
    if (op >= 0x90 && op <= 0x9F)
        return i;  
    if (op >= 0xA0 && op <= 0xA3)
        return need(4) ? i : 0;  
    if (op >= 0xA4 && op <= 0xA7)
        return i;  
    if (op == 0xA8)
        return need(1) ? i : 0;
    if (op == 0xA9)
        return need(immsz) ? i : 0;
    if (op >= 0xAA && op <= 0xAF)
        return i;  
    if (op >= 0xB0 && op <= 0xB7)
        return need(1) ? i : 0;  
    if (op >= 0xB8 && op <= 0xBF)
        return need(immsz) ? i : 0;  
    if (op == 0xC0 || op == 0xC1) {  
        if (modrm() == 0)
            return 0;
        return need(1) ? i : 0;
    }
    if (op == 0xC2)
        return need(2) ? i : 0;  
    if (op == 0xC3 || op == 0xC9)
        return i;  
    if (op == 0xC6 || op == 0xC7) {  
        if (modrm() == 0)
            return 0;
        return need(op == 0xC6 ? 1 : immsz) ? i : 0;
    }
    if (op == 0xC8)
        return need(3) ? i : 0;  
    if (op >= 0xCC && op <= 0xCF) {  
        if (op == 0xCD)
            return need(1) ? i : 0;
        return i;
    }
    if (op >= 0xD0 && op <= 0xD3)
        return modrm();  
    if (op == 0xD4 || op == 0xD5)
        return need(1) ? i : 0;  
    if (op == 0xD7)
        return i;  
    if (op >= 0xD8 && op <= 0xDF)
        return modrm();  
    if (op >= 0xE4 && op <= 0xE7)
        return need(1) ? i : 0;  
    if (op >= 0xEC && op <= 0xEF)
        return i;  
    if (op == 0xF4 || op == 0xF5)
        return i;  
    if (op == 0xF6 || op == 0xF7) {  
        const int m = ModRmLen(p, avail, &i);
        if (m < 0)
            return 0;
        if (((m >> 3) & 7) <= 1)
            return need(op == 0xF6 ? 1 : immsz) ? i : 0;
        return i;
    }
    if (op >= 0xF8 && op <= 0xFD)
        return i;  
    if (op == 0xFE || op == 0xFF)
        return modrm();  
    return 0;
}

enum RelocKind : uint8_t { kVerbatim = 0, kJccRel8, kJmpRel8, kRel32 };

enum RelocErr : int { kRelocOk = 0, kRelocDecode, kRelocTooMany, kRelocIntoRange, kRelocTooBig };

struct RelocDiag {
    int err = kRelocOk;
    int pos = 0;
    uint32_t target = 0;

};

struct StolenInsn {
    uint16_t srcPos;
    uint16_t dispPos;  
    uint8_t len;
    uint8_t kind;
    uint32_t target;  
};

constexpr uint32_t ReadU32(const uint8_t* p)
{
    return static_cast<uint32_t>(p[0]) | (static_cast<uint32_t>(p[1]) << 8) |
           (static_cast<uint32_t>(p[2]) << 16) | (static_cast<uint32_t>(p[3]) << 24);
}

constexpr void WriteU32(uint8_t* p, uint32_t v)
{
    p[0] = static_cast<uint8_t>(v);
    p[1] = static_cast<uint8_t>(v >> 8);
    p[2] = static_cast<uint8_t>(v >> 16);
    p[3] = static_cast<uint8_t>(v >> 24);
}

static constexpr int RelocateStolen(uint8_t* dst, int cap, uint32_t dstAddr, const uint8_t* src,
                                    uint32_t srcAddr, int stolen, RelocDiag* diag = nullptr)
{
    auto fail = [&](int err, int pos, uint32_t target) {
        if (diag) {
            diag->err = err;
            diag->pos = pos;
            diag->target = target;
        }
        return 0;
    };
    StolenInsn ins[64];
    int n = 0, out = 0;
    for (int pos = 0; pos < stolen; ) {
        const int len = InsnLen(src + pos, stolen - pos);
        if (len <= 0 || pos + len > stolen)
            return fail(kRelocDecode, pos, 0);
        if (n >= static_cast<int>(sizeof ins / sizeof ins[0]))
            return fail(kRelocTooMany, pos, 0);
        StolenInsn& s = ins[n++];
        s.srcPos = static_cast<uint16_t>(pos);
        s.len = static_cast<uint8_t>(len);
        s.kind = kVerbatim;
        s.target = 0;
        s.dispPos = 0;
        const uint8_t op = src[pos];
        int32_t disp = 0;
        if (op >= 0x70 && op <= 0x7F) {
            s.kind = kJccRel8;
            disp = static_cast<int8_t>(src[pos + len - 1]);
        } else if (op == 0xEB) {
            s.kind = kJmpRel8;
            disp = static_cast<int8_t>(src[pos + len - 1]);
        } else if (op == 0xE8 || op == 0xE9 || (op == 0x0F && src[pos + 1] >= 0x80 && src[pos + 1] <= 0x8F)) {
            s.kind = kRel32;
            disp = static_cast<int32_t>(ReadU32(src + pos + len - 4));
        }
        if (s.kind != kVerbatim) {
            s.target = srcAddr + pos + len + disp;
            const uint32_t off = s.target - srcAddr;
            if (off < static_cast<uint32_t>(stolen))
                return fail(kRelocIntoRange, pos, s.target);
            s.dispPos = static_cast<uint16_t>(out + (s.kind == kJccRel8 ? 2 : s.kind == kJmpRel8 ? 1 : len - 4));
            out += s.kind == kJccRel8 ? 6 : s.kind == kJmpRel8 ? 5 : len;
        } else {
            out += len;
        }
        pos += len;
    }
    out += 5;  
    if (dst && out > cap)
        return fail(kRelocTooBig, out, 0);
    if (!dst)
        return out;

    int o = 0;
    for (int k = 0; k < n; ++k) {
        const StolenInsn& s = ins[k];
        if (s.kind == kJccRel8) {
            dst[o] = 0x0F;
            dst[o + 1] = static_cast<uint8_t>(0x80 | (src[s.srcPos] & 0x0F));
            o += 6;
        } else if (s.kind == kJmpRel8) {
            dst[o] = 0xE9;
            o += 5;
        } else {
            for (int q = 0; q < s.len; ++q)
                dst[o + q] = src[s.srcPos + q];
            o += s.len;
        }
    }
    dst[o++] = 0xE9;
    WriteU32(dst + o, srcAddr + stolen - (dstAddr + out));
    o += 4;
    for (int k = 0; k < n; ++k) {
        const StolenInsn& s = ins[k];
        if (s.kind == kVerbatim)
            continue;
        WriteU32(dst + s.dispPos, s.target - (dstAddr + s.dispPos + 4));
    }
    return out;
}

struct RelocCase {
    const char* name;
    uint32_t srcAddr;
    int stolen;
    uint8_t src[16];
    bool refuse;  
    uint8_t expect[24];
    int expectLen;
};

constexpr uint32_t kSelfTestDst = 0x10000000;
constexpr RelocCase kRelocCases[] = {
    {"SetPath jne", 0x004DB3B0, 6, {0x83, 0x79, 0x04, 0xFF, 0x75, 0x21}, false,
     {0x83, 0x79, 0x04, 0xFF, 0x0F, 0x85, 0xCD, 0xB3, 0x4D, 0xF0, 0xE9, 0xA7, 0xB3, 0x4D, 0xF0}, 15},
    {"SetPathWide jne", 0x004DB3E0, 6, {0x83, 0x79, 0x04, 0xFF, 0x75, 0x1B}, false,
     {0x83, 0x79, 0x04, 0xFF, 0x0F, 0x85, 0xF7, 0xB3, 0x4D, 0xF0, 0xE9, 0xD7, 0xB3, 0x4D, 0xF0}, 15},
    {"plain copy", 0x004AE3C0, 7, {0x56, 0x8B, 0xF1, 0x83, 0x7E, 0x24, 0x00}, false,
     {0x56, 0x8B, 0xF1, 0x83, 0x7E, 0x24, 0x00, 0xE9, 0xBB, 0xE3, 0x4A, 0xF0}, 12},
    {"call rel32", 0x004DB3B0, 5, {0xE8, 0x00, 0x01, 0x00, 0x00}, false,
     {0xE8, 0xB0, 0xB4, 0x4D, 0xF0, 0xE9, 0xAB, 0xB3, 0x4D, 0xF0}, 10},
    {"jcc rel32", 0x004DB3B0, 6, {0x0F, 0x84, 0x00, 0x01, 0x00, 0x00}, false,
     {0x0F, 0x84, 0xB0, 0xB4, 0x4D, 0xF0, 0xE9, 0xAB, 0xB3, 0x4D, 0xF0}, 11},
    {"unknown opcode", 0x004DB3B0, 5, {0x0F, 0x0B, 0x90, 0x90, 0x90}, true, {}, 0},
    {"branch into copy", 0x004DB3B0, 5, {0x70, 0x02, 0x90, 0x90, 0x90}, true, {}, 0},
    {"prefixed branch", 0x004DB3B0, 5, {0x3E, 0x75, 0x40, 0x90, 0x90}, true, {}, 0},
};

constexpr bool RelocCaseOk(int idx)
{
    const RelocCase& c = kRelocCases[idx];
    uint8_t out[64] = {};
    const int len = RelocateStolen(out, 64, kSelfTestDst, c.src, c.srcAddr, c.stolen);
    if (c.refuse)
        return len == 0;
    if (len != c.expectLen)
        return false;
    for (int i = 0; i < len; ++i) {
        if (out[i] != c.expect[i])
            return false;
    }
    return true;
}
static_assert(RelocCaseOk(0), "trampoline relocation: SetPath jne case failed");
static_assert(RelocCaseOk(1), "trampoline relocation: SetPathWide jne case failed");
static_assert(RelocCaseOk(2), "trampoline relocation: plain copy case failed");
static_assert(RelocCaseOk(3), "trampoline relocation: call rel32 case failed");
static_assert(RelocCaseOk(4), "trampoline relocation: jcc rel32 case failed");
static_assert(RelocCaseOk(5), "trampoline relocation: unknown-opcode refusal case failed");
static_assert(RelocCaseOk(6), "trampoline relocation: branch-into-range refusal case failed");
static_assert(RelocCaseOk(7), "trampoline relocation: prefixed-branch refusal case failed");

static void RelocError(char* why, size_t whyCap, const RelocDiag& d, const uint8_t* src,
                       uint32_t address, int stolen)
{
    switch (d.err) {
    case kRelocDecode:
        std::snprintf(why, whyCap, "cannot decode instruction %02X at +%d in the stolen bytes",
                      src[d.pos], d.pos);
        break;
    case kRelocTooMany:
        std::snprintf(why, whyCap, "stolen bytes split into too many instructions");
        break;
    case kRelocIntoRange:
        std::snprintf(why, whyCap,
                      "branch at +%d targets 0x%08X inside the stolen range [0x%08X, 0x%08X)",
                      d.pos, d.target, address, address + stolen);
        break;
    case kRelocTooBig:
        std::snprintf(why, whyCap, "relocated prologue would be %d bytes", d.pos);
        break;
    default:
        std::snprintf(why, whyCap, "relocation failed");
        break;
    }
}

void* MakeTrampoline(uint32_t address, int stolen, char* why, size_t whyCap)
{
    
    constexpr size_t kTrampolineBytes = 64 * 1024;
    static uint8_t* page = static_cast<uint8_t*>(VirtualAlloc(nullptr, kTrampolineBytes, MEM_RESERVE | MEM_COMMIT, PAGE_EXECUTE_READWRITE));
    static size_t used = 0;
    if (!page) {
        std::snprintf(why, whyCap, "VirtualAlloc failed");
        return nullptr;
    }
    const auto* src = reinterpret_cast<const uint8_t*>(static_cast<uintptr_t>(address));
    RelocDiag d;
    const int len = RelocateStolen(nullptr, 0, 0, src, address, stolen, &d);
    if (!len) {
        RelocError(why, whyCap, d, src, address, stolen);
        return nullptr;
    }
    if (used + len > kTrampolineBytes) {
        std::snprintf(why, whyCap, "trampoline page full");
        return nullptr;
    }
    uint8_t* t = page + used;
    const int written = RelocateStolen(t, len, static_cast<uint32_t>(reinterpret_cast<uintptr_t>(t)), src,
                                       address, stolen, &d);
    if (written != len) {
        std::snprintf(why, whyCap, "internal error: relocation size changed between passes");
        return nullptr;
    }
    used += len;
    FlushInstructionCache(GetCurrentProcess(), t, len);
    return t;
}

static bool TrampolineSelfTest()
{
    bool ok = true;
    for (const RelocCase& c : kRelocCases) {
        uint8_t out[64];
        RelocDiag d;
        const int len = RelocateStolen(out, sizeof out, kSelfTestDst, c.src, c.srcAddr, c.stolen, &d);
        if (c.refuse) {
            if (len != 0) {
                Log("trampoline selftest FAIL %s: relocated, but must refuse", c.name);
                ok = false;
            }
            continue;
        }
        if (len != c.expectLen || std::memcmp(out, c.expect, static_cast<size_t>(len)) != 0) {
            char why[96] = "";
            if (d.err != kRelocOk)
                RelocError(why, sizeof why, d, c.src, c.srcAddr, c.stolen);
            Log("trampoline selftest FAIL %s: got %d bytes [%s], want %d [%s] (%s)", c.name, len,
                len > 0 ? Hex(out, static_cast<size_t>(len)).c_str() : "", c.expectLen,
                Hex(c.expect, c.expectLen).c_str(), why);
            ok = false;
        }
    }
    if (ok)
        Log("trampoline selftest: PASS (2 jne widened, 2 rel32 recomputed, 1 plain copy, 3 refusals)");
    return ok;
}

bool WriteJump(uint32_t address, const void* target)
{
    auto* p = reinterpret_cast<uint8_t*>(static_cast<uintptr_t>(address));
    DWORD old;
    if (!VirtualProtect(p, 5, PAGE_EXECUTE_READWRITE, &old))
        return false;
    const int32_t rel = static_cast<int32_t>(reinterpret_cast<uintptr_t>(target) - (address + 5));
    p[0] = 0xE9;
    std::memcpy(p + 1, &rel, 4);
    VirtualProtect(p, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), p, 5);
    return true;
}

std::wstring ModuleDir(HMODULE self)
{
    wchar_t path[MAX_PATH];
    GetModuleFileNameW(self, path, MAX_PATH);
    std::wstring dir(path);
    return dir.substr(0, dir.find_last_of(L"\\/") + 1);
}

